DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户名',
  `password` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码',
  `role_type` enum('admin','manager','tenant') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'tenant' COMMENT '角色',
  `area` varchar(100) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '负责区域',
  `name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '手机号',
  `id_card` varchar(30) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '身份证',
  `gender` enum('男','女') COLLATE utf8mb4_general_ci DEFAULT '男' COMMENT '性别',
  `age` int DEFAULT '0' COMMENT '年龄',
  `avatar` varchar(500) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '头像',
  `status` enum('active','inactive') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active' COMMENT '状态',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

