DROP TABLE IF EXISTS `houses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `houses` (
  `house_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '房源名称',
  `type` varchar(30) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '房型',
  `area` decimal(10,2) DEFAULT '0.00' COMMENT '面积(m²)',
  `floor` varchar(20) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '楼层',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '月租(元)',
  `deposit` decimal(10,2) DEFAULT '0.00' COMMENT '押金(元)',
  `address` varchar(200) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '地址',
  `description` text COLLATE utf8mb4_general_ci COMMENT '描述',
  `status` enum('available','reserved','rented') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'available' COMMENT '状态',
  `images` text COLLATE utf8mb4_general_ci COMMENT '图片(JSON数组)',
  `tags` varchar(500) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '标签(逗号分隔)',
  `facilities` varchar(500) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '设施(逗号分隔)',
  `manager_id` int DEFAULT NULL COMMENT '管理员ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`house_id`)
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='房源表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `houses` DISABLE KEYS */;
INSERT INTO `houses` VALUES (1,'阳光精品单间A-101','单间',25.00,'1层',2000.00,1200.00,'郑州市高新区科学大道100号A101','位于A栋1层，采光充足，配备独立卫浴、空调、热水器、衣柜、书桌椅等家具家电。距地铁站步行5分钟。','available','[]','近地铁,独立卫浴,朝南','',34,'2026-01-15 00:00:00'),(2,'标准单间A-202','单间',22.00,'2层',1000.00,1000.00,'郑州市高新区科学大道100号A202','A栋2层标准单间，南北通透，采光良好。配备独立卫浴和基础家电，性价比高。','reserved','[\"https://images.unsplash.com/photo-1555854877-bab0e564b8d5?w=600&h=400&fit=crop\",\"https://images.unsplash.com/photo-1560185007-cde436f6a4d0?w=600&h=400&fit=crop\",\"https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=600&h=400&fit=crop\"]','独立卫浴,WiFi,朝南','空调,热水器,WiFi,独立卫浴,衣柜,书桌椅',35,'2026-03-10 00:00:00'),(3,'雅致单间A-301','单间',28.00,'3层',1300.00,1300.00,'郑州市高新区科学大道100号A301','A栋3层雅致单间，暖色调装修风格，搭配原木家具，独立卫浴干湿分离。','available','[\"https://images.unsplash.com/photo-1598928506311-c55e324a6e3?w=600&h=400&fit=crop\",\"https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=600&h=400&fit=crop\",\"https://images.unsplash.com/photo-1560185127-6ed189bf02f4?w=600&h=400&fit=crop\"]','朝南,独立卫浴,近商圈','空调,热水器,洗衣机,WiFi,独立卫浴,衣柜,书桌椅',36,'2026-01-25 00:00:00'),(4,'豪华大床房A-401','单间',30.00,'4层',1500.00,1500.00,'郑州市高新区科学大道100号A401','A栋4层豪华单间，1.8m大床，超大观景阳台，装修精致。','rented','[\"https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=600&h=400&fit=crop\",\"https://images.unsplash.com/photo-1560185127-6ed189bf02f4?w=600&h=400&fit=crop\",\"https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=600&h=400&fit=crop\"]','大阳台,朝南,高层视野','空调,热水器,洗衣机,WiFi,独立卫浴,衣柜,大阳台',34,'2026-02-10 00:00:00'),(5,'双人间A-501','双人间',38.00,'5层',1600.00,1600.00,'郑州市高新区科学大道100号A501','A栋5层宽敞双人间，两张1.5m大床，高层采光好，窗外视野开阔。','rented','[\"https://images.unsplash.com/photo-1536376072261-38c75010e6c9?w=600&h=400&fit=crop\",\"https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=600&h=400&fit=crop\",\"https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=600&h=400&fit=crop\"]','近地铁,高层视野,可短租','空调,热水器,WiFi,独立卫浴,衣柜x2,书桌椅x2',35,'2026-02-18 00:00:00'),(6,'精品一室一厅A-601','一室一厅',38