/*!40000 ALTER TABLE `orders` ENABLE KEYS */;
DROP TABLE IF EXISTS `contracts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contracts` (
  `contract_id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL COMMENT '订单ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `house_id` int NOT NULL COMMENT '房源ID',
  `start_date` date NOT NULL COMMENT '开始日期',
  `end_date` date NOT NULL COMMENT '结束日期',
  `rent_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '月租金',
  `deposit` decimal(10,2) DEFAULT '0.00' COMMENT '押金',
  `status` enum('active','terminated','expired') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active' COMMENT '状态',
  `sign_date` date DEFAULT NULL COMMENT '签约日期',
  `content` text COLLATE utf8mb4_general_ci COMMENT '合同内容',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`contract_id`),
  KEY `order_id` (`order_id`),
  KEY `user_id` (`user_id`),
  KEY `house_id` (`house_id`),
  CONSTRAINT `contracts_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`order_id`) ON DELETE CASCADE,
  CONSTRAINT `contracts_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `contracts_ibfk_3` FOREIGN KEY (`house_id`) REFERENCES `houses` (`house_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='合同表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `contracts` DISABLE KEYS */;
