/*!40000 ALTER TABLE `contracts` ENABLE KEYS */;
DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `payment_id` int NOT NULL AUTO_INCREMENT,
  `contract_id` int NOT NULL COMMENT '合同ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `type` varchar(30) COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型(租金/押金/水费/电费)',
  `period` varchar(30) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '缴费周期',
  `status` enum('paid','unpaid') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'unpaid' COMMENT '状态',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `method` varchar(30) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '支付方式',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`payment_id`),
  KEY `contract_id` (`contract_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `payments_ibfk_1` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`contract_id`) ON DELETE CASCADE,
  CONSTRAINT `payments_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='缴费记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

