/*!40000 ALTER TABLE `payments` ENABLE KEYS */;
DROP TABLE IF EXISTS `announcements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `announcements` (
  `announcement_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `content` text COLLATE utf8mb4_general_ci COMMENT '内容',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`announcement_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='公告表';
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `announcements` DISABLE KEYS */;
INSERT INTO `announcements` VALUES (1,'关于2026年春节期间物业服务安排的通知','各位租户：\n\n2026年春节将至，为保障广大租户度过一个祥和、平安的节日，现将春节期间物业服务安排通知如下：\n\n一、服务时间安排\n春节期间（1月28日-2月4日），物业服务热线正常开通，服务时间为每日9:00-18:00。\n紧急维修请拨打24小时值班电话：400-888-9999。\n\n二、安全注意事项\n1. 外出租户请关好门窗、水电燃气，确保室内安全。\n2. 节日期间请勿在室内存放易燃易爆物品。\n3. 访客来访需在门岗登记，配合安保人员核验身份。\n\n三、便民服务\n物业中心春节期间提供快递代收、家政推荐等便民服务，如有需要请联系前台。\n\n祝各位租户新春快乐，阖家幸福！\n\n青年公寓物业服务中心\n2026年1月20日','2026-01-20 00:00:00'),(2,'公寓公共区域WiFi升级公告','各位租户：\n\n为提升租户上网体验，公寓将于2026年2月15日对公共区域WiFi进行系统升级。\n\n升级时间：2月15日 00:00-06:00\n升级范围：公寓大厅、花园、健身房、阅览室等公共区域\n\n升级内容：\n1. 网络带宽提升至千兆光纤\n2. 新增10个信号增强点，覆盖更全面\n3. 优化网络稳定性，降低延迟\n\n届时网络可能会有短暂中断，请提前做好准备。升级完成后，网络速度将提升3倍以上，使用体验将大幅改善。\n\n如有疑问，请联系物业服务中心。\n\n青年公寓物业服务中心\n2026年2月10日','2026-02-10 00:00:00'),(3,'3月消防安全演练通知','各位租户：\n\n根据消防部门要求，公寓将于2026年3月20日下午14:00-16:00进行消防安全演练。\n\n演练内容：\n1. 火灾警报响应与疏散演练\n2. 灭火器正确使用方法培训\n3. 消防栓操作演示\n4. 紧急逃生路线熟悉\n\n集合地点：公寓中心花园\n参与人员：全体租户\n\n请各位租户积极配合，届时听到警报后请有序沿安全通道撤离至集合地点。演练过程中请勿乘坐电梯，听从工作人员指挥。\n\n消防安全，人人有责。通过演练提高消防安全意识，掌握逃生自救技能，共同维护公寓安全环境。\n\n青年公寓物业服务中心\n2026年3月15日','2026-03-10 00:00:00'),(4,'F栋新楼正式开放入住公告','各位租户：\n\n经过三个月的精心装修，F栋新楼已于2026年3月1日正式完工，即日起开放预约看房！\n\nF栋房源亮点：\n★ 全新精装修，拎包入住\n★ 配备独立卫浴、空调、冰箱、洗衣机\n★ 全屋智能家居系统，手机远程控制\n★ 高楼层视野开阔，采光充足\n★ 24小时安保监控，安全无忧\n\n房型面积：25-60平米单间、一室一厅\n租金范围：1200-2800元/月\n\n优惠政策：\n首批入住租户可享首月租金8折优惠！\n签约一年送一个月免租期！\n\n预约看房热线：400-888-9999\n或前往物业服务中心前台咨询\n\n欢迎各位租户前来参观！\n\n青年公寓管理部\n2026年3月5日','2026-03-15 00:00:00'),(5,'关于调整水电费计费方式的通知','各位租户：\n\n为响应国家节能减排号召，促进资源合理利用，自2026年4月1日起，公寓水电费将采用阶梯计费方式。\n\n调整内容如下：\n\n【水费计费标准】\n第一阶梯：月用水量0-10吨，按4.5元/吨计费\n第二阶梯：月用水量10-20吨，按6.0元/吨计费\n第三阶梯：月用水量20吨以上，按8.0元/吨计费\n\n【电费计费标准】\n第一阶梯：月用电量0-100度，按0.55元/度计费\n第二阶梯：月用电量100-200度，按0.65元/度计费\n第三阶梯：月用电量200度以上，按0.85元/度计费\n\n此次调整旨在鼓励大家节约用水用电，共同建设绿色环保公寓。月用量在第一阶梯范围内的租户，费用基本不受影响。\n\n如有疑问，请咨询物业服务中心。\n\n青年公寓物业服务中心\n2026年3月25日','2026-03-22 00:00:00');
